# turn on HTTP/3
listen 443 quic reuseport;
listen 443 ssl;            # keep TCP for h2/h1.1

# advertise h3 to every client for a full week
add_header Alt-Svc 'h3=":443"; ma=604800';

ssl_protocols TLSv1.2 TLSv1.3;
ssl_early_data on;         # 0-RTT for the latency win

# (no change to net.core.rmem_max / wmem_max)
